from eai_manipulator_msgs.action import JointSpace, EndPosSingleTarget


class ActionServerConfig:
    """Action服务器配置基类"""
    def __init__(self, action_name, action_type, controller_name, controller_action_suffix='jointspace'):
        self.action_name = action_name
        self.action_type = action_type
        self.controller_name = controller_name
        self.controller_action_name = f'/{controller_name}/{controller_action_suffix}'

    def create_goal_msg(self, incoming_goal):
        """从传入的goal创建发送给控制器的goal消息"""
        raise NotImplementedError

    def create_result_msg(self, controller_result):
        """从控制器的result创建返回给客户端的result消息"""
        raise NotImplementedError


class JointSpaceActionConfig(ActionServerConfig):
    """JointSpace action配置"""
    def __init__(self, action_name, controller_name):
        super().__init__(action_name, JointSpace, controller_name, 'jointspace')

    def create_goal_msg(self, incoming_goal):
        goal_msg = JointSpace.Goal()
        goal_msg.target_positions = incoming_goal.target_positions
        return goal_msg

    def create_result_msg(self, controller_result):
        result_msg = JointSpace.Result()
        result_msg.success = False
        result_msg.result_msg = ""
        if controller_result is not None:
            result_msg.success = controller_result.success
            result_msg.result_msg = controller_result.result_msg
        return result_msg


class EndPosSingleTargetActionConfig(ActionServerConfig):
    """EndPosSingleTarget action配置"""
    def __init__(self, action_name, controller_name):
        super().__init__(action_name, EndPosSingleTarget, controller_name, 'endPosSingleTarget')

    def create_goal_msg(self, incoming_goal):
        goal_msg = EndPosSingleTarget.Goal()
        goal_msg.target = incoming_goal.target
        return goal_msg

    def create_result_msg(self, controller_result):
        result_msg = EndPosSingleTarget.Result()
        result_msg.success = False
        result_msg.result_msg = ""
        if controller_result is not None:
            result_msg.success = controller_result.success
            result_msg.result_msg = controller_result.result_msg
        return result_msg


# Action配置注册表 - 在此添加新的action类型
ACTION_CONFIGS = {
    # JointSpace action
    '/xarm/jointspace_arm_L': lambda: JointSpaceActionConfig('/xarm/jointspace_arm_L', 'jointspace_arm_L_controller'),
    '/xarm/jointspace_arm_R': lambda: JointSpaceActionConfig('/xarm/jointspace_arm_R', 'jointspace_arm_R_controller'),
    # EndPosSingleTarget action
    '/xarm/endpose_arm_L': lambda: EndPosSingleTargetActionConfig('/xarm/endpose_arm_L', 'endpose_single_arm_qp_L_controller'),
    '/xarm/endpose_arm_R': lambda: EndPosSingleTargetActionConfig('/xarm/endpose_arm_R', 'endpose_single_arm_qp_R_controller'),
}


def get_all_action_configs():
    """获取所有注册的action配置"""
    return {name: factory() for name, factory in ACTION_CONFIGS.items()}
